/*
 * A354266  Pairs of integers (s, t) such that 0 < s < t and gcd(s, t) > 1,
 *          where the pairs are generated by the boustrophedonic Cantor
 *          enumeration A319571.
 * https://oeis.org/A354266
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth element of the flattened list of pairs (s,t) with
 *            0 < s < t and gcd(s,t) > 1, enumerated in boustrophedonic Cantor
 *            order: increasing sum s+t, then increasing s on each diagonal
 * Range:     u8 n <= 76, u16 n <= 76, u32 n <= 76, u64 n <= 76, u128 n <= 76,
 *            big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/gcd.h"

seq_t a(idx_t n) {
    if (n == 0) return 0;           // offset is 1; undefined for n=0
    idx_t count = 0;                // count of emitted numbers
    for (idx_t d = 3; ; ++d) {      // start with smallest sum allowing s < t
        for (idx_t s = 1; s < d; ++s) {
            idx_t t = d - s;
            if (s >= t) continue;   // enforce 0 < s < t
            if (gcd((seq_t)s, (seq_t)t) <= (seq_t)1) continue; // gcd > 1
            ++count;
            if (count == n) return (seq_t)s;
            ++count;
            if (count == n) return (seq_t)t;
        }
    }
}
